// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        address initialOwner = newOwner;
        bool ok;
        try c.setOwner(initialOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok == true);

        vm.prank(caller);
        bool ok2;
        try c.setOwner(address(0x1234)) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        if (caller != address(this)) {
            assertTrue(ok2 == false);
        } else {
            assertTrue(ok2 == true);
        }
    }
}
